        System.out.println(climbStairs(n));
    }

    static long climbStairs(int n) {
        long prev2 = 1, prev1 = 1;
        for (int i = 2; i <= n; i++) {
            long cur = prev1 + prev2;
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }
}

