public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] heights = new int[n];
        for (int i = 0; i < n; i++) heights[i] = sc.nextInt();
        System.out.println(frogMinEnergy(heights));
    }

    static int frogMinEnergy(int[] heights) {
        int n = heights.length;
        int[] dp = new int[n];
        dp[0] = 0;
        for (int i = 1; i < n; i++) {
            int best = dp[i - 1] + Math.abs(heights[i] - heights[i - 1]);
            if (i >= 2) {
                int two = dp[i - 2] + Math.abs(heights[i] - heights[i - 2]);
                if (two < best) best = two;
            }
            dp[i] = best;
        }
        return dp[n - 1];
    }
}

