public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int target = sc.nextInt(), n = sc.nextInt();
        int[] items = new int[n];
        for (int i = 0; i < n; i++) items[i] = sc.nextInt();
        System.out.println(subsetSumExists(target, items));
    }

    static int subsetSumExists(int target, int[] items) {
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;
        for (int v : items) {
            for (int t = target; t >= v; t--) {
                if (dp[t - v]) dp[t] = true;
            }
        }
        return dp[target] ? 1 : 0;
    }
}

