public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int month = sc.nextInt();
        System.out.println(colonySize(month));
    }

    static long colonySize(int month) {
        long[] memo = new long[month + 1];
        return grow(month, memo);
    }

    static long grow(int month, long[] memo) {
        if (month <= 2) return month + 1;
        if (memo[month] != 0) return memo[month];
        memo[month] = grow(month - 1, memo) + 2 * grow(month - 2, memo);
        return memo[month];
    }
}

