public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int capacity = sc.nextInt(), n = sc.nextInt();
        int[] weights = new int[n];
        for (int i = 0; i < n; i++) weights[i] = sc.nextInt();
        int[] values = new int[n];
        for (int i = 0; i < n; i++) values[i] = sc.nextInt();
        so.println(knapsack(capacity, weights, values));
    }

    static int knapsack(int capacity, int[] weights, int[] values) {
        int n = weights.length;
        int[] dp = new int[capacity + 1];
        for (int i = 0; i < n; i++) {
            for (int cap = capacity; cap >= weights[i]; cap--) {
                int cand = dp[cap - weights[i]] + values[i];
                if (cand > dp[cap]) dp[cap] = cand;
            }
        }
        return dp[capacity];
    }
}

