public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] valuables = new int[n];
        for (int i = 0; i < n; i++) valuables[i] = sc.nextInt();
        so.println(maxLoot(valuables));
    }

    static long maxLoot(int[] valuables) {
        long[] memo = new long[valuables.length];
        Arrays.fill(memo, -1);
        return robFrom(valuables, 0, memo);
    }

    static long robFrom(int[] valuables, int i, long[] memo) {
        if (i >= valuables.length) return 0;
        if (memo[i] != -1) return memo[i];
        long skip = robFrom(valuables, i + 1, memo);
        long take = valuables[i] + robFrom(valuables, i + 2, memo);
        memo[i] = Math.max(skip, take);
        return memo[i];
    }
}

