public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] price = new int[n + 1];
        for (int i = 1; i <= n; i++) price[i] = sc.nextInt();
        so.println(rodProfit(n, price));
    }

    static int rodProfit(int n, int[] price) {
        int[] dp = new int[n + 1];
        for (int len = 1; len <= n; len++) {
            for (int cut = 1; cut <= len; cut++) {
                int cand = price[cut] + dp[len - cut];
                if (cand > dp[len]) dp[len] = cand;
            }
        }
        return dp[n];
    }
}

