public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        int[][] grid = new int[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) grid[i][j] = sc.nextInt();
        }
        so.println(countRoutes(grid));
    }

    static long countRoutes(int[][] grid) {
        int r = grid.length, c = grid[0].length;
        long[][] dp = new long[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (grid[i][j] == 1) continue;
                if (i == 0 && j == 0) {
                    dp[i][j] = 1;
                    continue;
                }
                long up = i > 0 ? dp[i - 1][j] : 0;
                long left = j > 0 ? dp[i][j - 1] : 0;
                dp[i][j] = up + left;
            }
        }
        return dp[r - 1][c - 1];
    }
}

