public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int target = sc.nextInt(), n = sc.nextInt();
        int[] values = new int[n];
        for (int i = 0; i < n; i++) values[i] = sc.nextInt();
        so.println(countSubsets(target, values));
    }

    static long countSubsets(int target, int[] values) {
        long[] dp = new long[target + 1];
        dp[0] = 1;
        for (int v : values) {
            for (int t = target; t >= v; t--) {
                dp[t] += dp[t - v];
            }
        }
        return dp[target];
    }
}
